void Solver::bump_var(int var, double coeff) {
    constexpr double LIMIT   = 1e100;
    constexpr double RESCALE = 1e-100;

    if (coeff == 0.0) return;                     // nothing to do

    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;

    if (newAct > LIMIT) {
        // Rescale all activities without extra bounds checks
        double *ptr = activity + 1;               // activity[0] is unused
        for (int i = vars; i > 0; --i) {
            *ptr++ *= RESCALE;
        }
        var_inc *= RESCALE;
    }

    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
